Status source(const TaskShopOrderContactContext& x,const TaskShopOrderContactStart& s){
 const auto& c=x.common;const auto* b=binding(x.orders,s.task_id);const auto* head=c.state().facts.find(s.fact_id);const auto f=serial(c,s.fact_id,task_shop_order_contact_started_kind),a=serial(c,s.action_id,"action"),session=serial(c,s.session_id,"interaction"),accepted=serial(c,s.acceptance_fact_id,task_shop_order_acceptance_prefix);auto now=through(c,x.phase);
 if(!now.ok)return {false,{},now.error};
 if(!b||!head||head->id!=s.fact_id||head->kind!=task_shop_order_contact_started_kind||head->domain!=task_shop_order_contact_module||!f||!a||*f-*a!=1||!session||*session>=*a||!accepted||*accepted>=*a||s.acceptance_fact_id!=b->fact_id||s.order_issue_fact_id!=b->order_issue_fact_id||s.order_id!=b->order_id||s.proprietor_actor_id!=b->terms.proprietor_actor_id||b->terms.original_client.kind!=Owner::Kind::actor||b->terms.original_client.extra||s.client_actor_id!=b->terms.original_client.id||s.client_actor_id==s.proprietor_actor_id||s.started_tick<b->terms.accepted_tick||s.started_tick>c.tick()||!task_finish_within(s.started_tick,task_handover_ticks,b->terms.deadline_tick)||!before(c,b->fact_id,s.fact_id)||!context(s.context,s.context)||s.context.provider_actor_id!=s.client_actor_id)return common_failure("InvalidTaskShopOrderContactSource",s.fact_id);
 if(x.submitter_mode==TaskShopOrderContactSubmitterMode::unavailable)return common_failure("TaskShopOrderContactSubmitterModeRequired",s.fact_id);if(x.submitter_mode==TaskShopOrderContactSubmitterMode::controlled_player){if(!x.player_before)return common_failure("TaskShopOrderContactPlayerSourceRequired",s.fact_id);auto player=x.player_before(s.started_tick,s.fact_id);if(!player.ok)return {false,{},player.error};if(player.value!=s.proprietor_actor_id)return common_failure("TaskShopOrderContactHistoricalPlayerMismatch",s.fact_id);}
 auto issued=x.issued_orders.private_shop_order_source(s.order_id);if(!issued.ok)return {false,{},issued.error};if(!issued.value||!identity(issued.value->source_identity,c.state().identity)||issued.value->status!="accepted"||issued.value->task_id!=s.task_id||issued.value->acceptance_fact_id!=s.acceptance_fact_id||issued.value->issue_fact_id!=s.order_issue_fact_id||!task_shop_order_terms_equal(issued.value->terms,b->terms))return common_failure("TaskShopOrderContactIssuedSourceMismatch",s.fact_id);
 const auto& d=issued.value->client_declaration;const auto* role=x.interaction_catalog.common?x.interaction_catalog.common->roles.find(s.context.role_id):nullptr;
 if(s.context.place_id!=d.place_id||s.context.role_id!=d.role_id||s.context.provider_actor_id!=d.provider_actor_id||s.dialogue_id!=d.dialogue_id||s.node_id!=d.node_id||!role||role->organization_id||role->initial_actor!=s.client_actor_id||role->place_id!=s.context.place_id||!role->dialogue_id||*role->dialogue_id!=s.dialogue_id)return common_failure("TaskShopOrderContactOriginalClientRequired",s.fact_id);
 const DialogueDefinition* dialogue=nullptr;for(const auto& v:x.interaction_catalog.dialogues)if(v.id==s.dialogue_id){if(dialogue)return common_failure("TaskShopOrderContactDialogueMismatch",s.fact_id);dialogue=&v;}const DialogueNode* node=nullptr;if(dialogue)for(const auto& n:dialogue->nodes)if(n.id==s.node_id){if(node)return common_failure("TaskShopOrderContactDialogueMismatch",s.fact_id);node=&n;}
 if(!dialogue||dialogue->context_role!=s.context.role_id||!node||node->kind!="say"||(node->speaker!="$provider"&&node->speaker!=s.client_actor_id))return common_failure("TaskShopOrderContactProviderSayRequired",s.fact_id);
 auto valid=presence(x,s.proprietor_actor_id,s.started_tick,s.fact_id);if(!valid.ok)return valid;return presence(x,s.client_actor_id,s.started_tick,s.fact_id);
}
