Status validate_task_shop_order_contacts(const TaskShopOrderContactContext& x){
 using namespace shop_contact_detail;auto valid=validate_task_shop_order_execution(x.common,x.tasks,x.orders,x.issued_orders,x.phase);if(!valid.ok)return valid;if(x.contacts.version!=1)return common_failure("UnsupportedTaskShopOrderContactVersion");
 std::set<StableId> actions;Integer previous=0;const auto& facts=x.common.state().facts.order();std::size_t previous_position=0;bool first=true;
 for(const auto& row:x.contacts.starts.rows()){const auto& s=row.second;if(row.first!=s.fact_id||!actions.insert(s.action_id).second)return common_failure("DuplicateTaskShopOrderContact",row.first);valid=source(x,s);if(!valid.ok)return valid;auto n=serial(x.common,row.first,task_shop_order_contact_started_kind);auto at=std::find(facts.begin(),facts.end(),row.first);auto position=static_cast<std::size_t>(at-facts.begin());if(!n||*n<=previous||(!first&&position<=previous_position))return common_failure("TaskShopOrderContactOrderMismatch",row.first);previous=*n;previous_position=position;first=false;
  Integer matches=0;if(const auto* active=x.orders.actions.find(s.action_id)){if(!work(s,*active))return common_failure("TaskShopOrderActiveContactMismatch",row.first);++matches;}
  for(const auto& r:x.orders.interruptions.rows())if(r.second.source.action_id==s.action_id){const auto end=serial(x.common,r.first,task_shop_order_interrupted_kind);if(!work(s,r.second.source)||!end||*n>=*end||!before(x.common,s.fact_id,r.first))return common_failure("TaskShopOrderInterruptedContactMismatch",row.first);++matches;}
  for(const auto& r:x.orders.settlements.rows())if(r.second.outcome=="delivered"&&r.second.source_action_id==s.action_id){const auto& done=r.second;const auto end=serial(x.common,done.settlement_id,"settlement");if(done.task_id!=s.task_id||done.order_id!=s.order_id||done.action_started_tick!=s.started_tick||!end||*n>=*end||!before(x.common,s.fact_id,r.first)||!s.actual_result)return common_failure("TaskShopOrderDeliveredContactMismatch",row.first);const auto result=serial(x.common,s.actual_result->result_id,"result");if(!result||*result>=*end)return common_failure("TaskShopOrderContactResultAfterDelivery",row.first);valid=presence(x,s.proprietor_actor_id,done.tick,r.first);if(!valid.ok)return valid;valid=presence(x,s.client_actor_id,done.tick,r.first);if(!valid.ok)return valid;++matches;}
  if(matches!=1)return common_failure("TaskShopOrderContactOutcomeMissing",row.first);
 }
 for(const auto& r:x.orders.actions.rows())if(!actions.count(r.first))return common_failure("MissingTaskShopOrderActiveContact",r.first);
 for(const auto& r:x.orders.interruptions.rows())if(!actions.count(r.second.source.action_id))return common_failure("MissingTaskShopOrderInterruptedContact",r.first);
 for(const auto& r:x.orders.settlements.rows())if(r.second.outcome=="delivered"&&!actions.count(r.second.source_action_id))return common_failure("MissingTaskShopOrderDeliveredContact",r.first);
 for(const auto& r:x.common.state().facts.rows())if(r.second.domain==task_shop_order_contact_module||r.second.kind==task_shop_order_contact_started_kind){if(r.second.domain!=task_shop_order_contact_module||r.second.kind!=task_shop_order_contact_started_kind||!x.contacts.starts.find(r.first))return common_failure("TaskShopOrderContactPayloadRequired",r.first);}
 return validate_task_shop_order_contact_results(x.common,x.contacts);
}
